function ResolveDownloadDir{$pref=Join-Path $UserData 'Default\Preferences';if(Test-Path -LiteralPath $pref){try{$j=Get-Content -LiteralPath $pref -Raw -Encoding UTF8|ConvertFrom-Json;$p=[string]$j.download.default_directory;if($p-and(Test-Path -LiteralPath $p -PathType Container)){return [pscustomobject]@{path=$p;source='CHROME_PREFERENCE'}}}catch{}};$p=Join-Path $env:USERPROFILE 'Downloads';if(Test-Path -LiteralPath $p -PathType Container){return [pscustomobject]@{path=$p;source='WINDOWS_DOWNLOADS'}};throw 'NO_DOWNLOAD_DIRECTORY'}
function ResolveDriveProjectPath{$hits=@();foreach($d in @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)){$r=[string]$d.Root;if(-not$r){continue};foreach($base in @((Join-Path $r $MyDriveKo),(Join-Path $r 'My Drive'),(Join-Path $r 'Google Drive'))){if(-not(Test-Path -LiteralPath $base -PathType Container)){continue};$p=Join-Path $base ($FactoryName+'\'+$OutputName+'\'+$ProjectKey);if(Test-Path -LiteralPath $p -PathType Container){$hits+=$p}}};@($hits|Select-Object -Unique)}
function NewestCompleted([string]$dir,[datetime]$since){@(Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue|Where-Object{$_.LastWriteTime-ge$since.AddSeconds(-2)-and$_.Length-gt0-and$_.Extension-notin@('.crdownload','.part','.tmp')}|Sort-Object LastWriteTime -Descending|Select-Object -First 10)}
