  $r.stage='EXACT_CARD';$titleJson=$ExactTitle|ConvertTo-Json -Compress;$x=Eval $w ([ref]$q) "(() => {const wanted=String($titleJson),v=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'};const all=[...document.querySelectorAll('div,section,article,[role=group],[role=region]')].filter(v).filter(e=>String(e.innerText||e.textContent||'').includes(wanted)).sort((a,b)=>String(a.innerText||'').length-String(b.innerText||'').length);for(const root of all){const text=String(root.innerText||root.textContent||'');if(!text.includes(wanted))continue;const bs=[...root.querySelectorAll('button,[role=button]')].filter(v);const more=bs.find(b=>{const t=String([b.innerText,b.textContent,b.getAttribute('aria-label'),b.getAttribute('title'),b.querySelector('mat-icon')?.textContent].join(' '));return /more_vert|more|menu/i.test(t)||t.includes(String.fromCharCode(45908,48372,44592))});if(more){const z=more.getBoundingClientRect();return{ok:true,x:z.left+z.width/2,y:z.top+z.height/2,text:text.slice(0,1200),candidateCount:all.length}}}return{ok:false,candidateCount:all.length,body:String(document.body?.innerText||'').slice(0,3000)}})()";if(-not$x.ok){throw 'EXACT_FRESH_AUDIO_CARD_MENU_NOT_FOUND'};$r.exactTitleMatched=$true;$r.cardEvidence=$x;Click $w ([ref]$q) $x.x $x.y;$r.menuClicked=$true;Start-Sleep -Milliseconds 600
